async function refreshAuthUI() {
  const {
    data: { session },
  } = await window.supabaseClient.auth.getSession();
  const user = session?.user;

  if (!user) {
    authToken = null;
    currentUser = null;
    currentUserRole = null;
    currentUserName = null;
    currentPortal = "customer";
    updateUserUI();
    return;
  }

  const { data: profile, error: profileError } = await window.supabaseClient
    .from("profiles")
    .select("first_name,last_name,phone,role")
    .eq("id", user.id)
    .maybeSingle();
  if (profileError) {
    console.warn("Unable to load account profile:", profileError.message);
  }
  const { data: vendorRequest, error: vendorError } = await window.supabaseClient
    .from("vendor_requests")
    .select("status,business_name")
    .eq("user_id", user.id)
    .maybeSingle();
  if (vendorError) {
    console.warn("Unable to load vendor profile:", vendorError.message);
  }

  currentUser = {
    id: user.id,
    email: user.email,
    firstName: profile?.first_name || user.user_metadata?.first_name || "",
    lastName: profile?.last_name || user.user_metadata?.last_name || "",
    phone: profile?.phone || user.user_metadata?.phone || "",
    role: profile?.role || "customer",
    isVendor: vendorRequest?.status === "approved",
    vendorBusinessName: vendorRequest?.business_name || "",
  };

  authToken = null;
  safeLocalStorageRemove("NAKA_user_token");
  safeLocalStorageRemove("NAKA_user_role");
  currentUserRole = currentUser.role;
  currentUserName = currentUser.firstName || user.email;
  currentPortal =
    currentUser.isVendor && safeLocalStorageGet("NAKA_portal_mode") === "vendor"
      ? "vendor"
      : "customer";

  updateUserUI();
}

async function restoreCustomerOrAdminSession() {
  try {
    const {
      data: { session },
    } = await window.supabaseClient.auth.getSession();
    if (session?.user) {
      await refreshAuthUI();
      return;
    }
  } catch (error) {
    console.warn("Unable to restore customer session:", error);
  }
  await restoreAdminSession();
}

function openVendorApplicationFromEmail() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("vendor_application") !== "1" || !currentUser) return;

  currentPortal = "customer";
  safeLocalStorageSet("NAKA_portal_mode", "customer");
  openAccount(null, "vendor");

  if (!currentUser.isVendor) {
    const form = document.getElementById("vendor-application-form");
    if (form) form.style.display = "block";
  }

  const cleanUrl = new URL(window.location.href);
  cleanUrl.searchParams.delete("vendor_application");
  history.replaceState(null, "", cleanUrl.pathname + cleanUrl.search + cleanUrl.hash);
}

