  async function forgotPassword(e) {
  if (e) e.preventDefault();

  const emailInput = document.getElementById("login-username");
  const errorEl = document.getElementById("login-error");

  const email = emailInput.value.trim().toLowerCase();

  errorEl.className = "modal-error";
  errorEl.style.display = "none";
  errorEl.textContent = "";

  if (!email || !email.includes("@")) {
    errorEl.textContent =
      "Enter your email address above first, then click Forgot password.";
    errorEl.style.display = "block";
    emailInput.focus();
    return;
  }

  try {
    const { error } =
      await window.supabaseClient.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin + window.location.pathname,
      });

    if (error) {
      throw error;
    }

    errorEl.className = "modal-success";
    errorEl.textContent =
      "Password reset email sent. Check your inbox and follow the link to create a new password.";
    errorEl.style.display = "block";
  } catch (error) {
    console.error("Password reset error:", error);

    errorEl.className = "modal-error";
    errorEl.textContent =
      error.message || "Unable to send password reset email. Please try again.";
    errorEl.style.display = "block";
  }
}

      function openResetPasswordModal() {
        closeLoginModal();
        const errorEl = document.getElementById("reset-password-error");
        const successEl = document.getElementById("reset-password-success");
        errorEl.textContent = "";
        errorEl.style.display = "none";
        successEl.textContent = "";
        successEl.style.display = "none";
        document.getElementById("reset-password").value = "";
        document.getElementById("reset-password-confirm").value = "";
        document.getElementById("reset-password-modal").classList.add("open");
        document.getElementById("reset-password").focus();
      }

      function closeResetPasswordModal() {
        document.getElementById("reset-password-modal").classList.remove("open");
      }

      async function updatePassword() {
        const password = document.getElementById("reset-password").value;
        const confirmPassword = document.getElementById("reset-password-confirm").value;
        const errorEl = document.getElementById("reset-password-error");
        const successEl = document.getElementById("reset-password-success");
        errorEl.textContent = "";
        errorEl.style.display = "none";
        successEl.textContent = "";
        successEl.style.display = "none";

        if (password.length < 8) {
          errorEl.textContent = "Your new password must be at least 8 characters.";
          errorEl.style.display = "block";
          return;
        }
        if (password !== confirmPassword) {
          errorEl.textContent = "Your passwords do not match.";
          errorEl.style.display = "block";
          return;
        }

        try {
          const { error } = await window.supabaseClient.auth.updateUser({ password });
          if (error) throw error;
          successEl.textContent = "Password updated successfully. You can now continue using your account.";
          successEl.style.display = "block";
          document.getElementById("reset-password").value = "";
          document.getElementById("reset-password-confirm").value = "";
        } catch (error) {
          errorEl.textContent = error.message || "Your reset link has expired. Please request a new password reset email.";
          errorEl.style.display = "block";
        }
      }

