      async function restoreAdminSession() {
        const saved = safeLocalStorageGet("NAKA_user_token");
        if (!saved) return;
        authToken = saved;
        try {
          const role = safeLocalStorageGet("NAKA_user_role");
          const res = await fetch(
            role === "customer" ? "/api/auth/me" : "/api/admin/me",
            {
              headers: { Authorization: "Bearer " + authToken },
            },
          );
          if (!res.ok) throw new Error("invalid session");
          const data = await res.json();
          currentUserRole =
            role === "customer" ? data.user.role : data.role || "admin";
          currentUser = data.user || null;
          currentUserName = currentUser
            ? currentUser.firstName
            : data.username || null;
        } catch (e) {
          authToken = null;
          currentUserRole = null;
          currentUserName = null;
          safeLocalStorageRemove("NAKA_user_token");
          safeLocalStorageRemove("NAKA_user_role");
        }
        updateUserUI();
      }

      function isAdmin() {
        return currentUserRole === "admin";
      }

