      async function requestVendorApplication() {
        const message = document.getElementById("vendor-message");
        const button = document.querySelector('[onclick="requestVendorApplication()"]');
        if (button) {
          button.disabled = true;
          button.textContent = "Sending…";
        }
        try {
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again before requesting the application link.");
          const res = await fetch("/api/vendor-requests/start", { method: "POST", headers: { Authorization: "Bearer " + token } });
          const data = await res.json().catch(() => ({}));
          message.className = res.ok ? "modal-success" : "modal-error";
          message.textContent = data.message || data.error || "Unable to send the vendor application link.";
          if (res.ok && data.canContinue) {
            const form = document.getElementById("vendor-application-form");
            if (form) form.style.display = "block";
          }
        } catch (error) {
          message.className = "modal-error";
          message.textContent = error.message || "Unable to send the vendor application link.";
        } finally {
          if (button) {
            button.disabled = false;
            button.textContent = "Email Me the Application Link";
          }
        }
        message.style.display = "block";
      }

      async function completeVendorApplication() {
        const message = document.getElementById("vendor-message");
        try {
          const applicationForm = document.getElementById("vendor-application-form");
          const fields = applicationForm ? [...applicationForm.querySelectorAll("input, select, textarea")] : [];
          const invalidField = fields.find((field) => !field.checkValidity());
          if (invalidField) {
            invalidField.reportValidity();
            throw new Error("Please complete all required business fields correctly.");
          }
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again before creating your vendor profile.");
          const res = await fetch("/api/vendor-requests/complete", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Bearer " + token,
            },
            body: JSON.stringify({
              businessName: document.getElementById("vendor-business-name").value.trim(),
              contactName: document.getElementById("vendor-contact-name").value.trim(),
              phone: document.getElementById("vendor-phone").value.trim(),
              businessType: document.getElementById("vendor-business-type").value,
              registrationNumber: document.getElementById("vendor-registration-number").value.trim(),
              taxNumber: document.getElementById("vendor-tax-number").value.trim(),
              websiteUrl: document.getElementById("vendor-website-url").value.trim(),
              socialMediaUrl: document.getElementById("vendor-social-media-url").value.trim(),
              streetAddress: document.getElementById("vendor-street-address").value.trim(),
              city: document.getElementById("vendor-city").value.trim(),
              province: document.getElementById("vendor-province").value.trim(),
              postalCode: document.getElementById("vendor-postal-code").value.trim(),
              businessDescription: document.getElementById("vendor-business-description").value.trim(),
            }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) throw new Error(data.error || "Unable to create your vendor profile.");
          await refreshAuthUI();
          openAccount(null, "vendor");
          const refreshedMessage = document.getElementById("vendor-message");
          refreshedMessage.className = "modal-success";
          refreshedMessage.textContent = data.message || "Your vendor profile is ready.";
          refreshedMessage.style.display = "block";
        } catch (error) {
          message.className = "modal-error";
          message.textContent = error.message || "Unable to create your vendor profile.";
          message.style.display = "block";
        }
      }

      function vendorProductFormMarkup() {
        return `<form id="vendor-product-form" class="admin-edit-panel" style="display:block" onsubmit="saveVendorProduct(event)">
          <input type="hidden" id="vendor-product-id">
          <div class="admin-edit-panel-head"><span id="vendor-product-editor-title">Vendor · Add Product</span><button type="button" class="admin-editor-close" onclick="resetVendorProductForm()" aria-label="Clear editor">&times;</button></div>
          <div class="admin-field"><label>Product Images (up to 8)</label><button type="button" class="admin-file-btn" onclick="document.getElementById('vendor-img-file').click()">+ Add Images</button><input type="file" id="vendor-img-file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden onchange="handleVendorImagesChosen(event)"><div class="vendor-image-manager" id="vendor-image-gallery"></div><small class="checkout-copy">The first image is used as the main catalogue image. Each image must be 2 MB or smaller.</small></div>
          <div class="admin-field"><label>Name *</label><input type="text" id="vendor-product-name" maxlength="160" required></div>
          <div class="admin-field-row"><div class="admin-field"><label>Product Type *</label><input type="text" id="vendor-product-type" maxlength="100" placeholder="Wig, bundle, closure…" required></div><div class="admin-field"><label>Hair Type *</label><input type="text" id="vendor-product-hair-type" maxlength="100" placeholder="Straight, curly, body wave…" required></div></div>
          <div class="admin-field-row"><div class="admin-field"><label>Collection *</label><select class="field-input" id="vendor-product-collection" required><option value="everyday">Glam On A Budget</option><option value="signature">Signature Collection</option><option value="luxe">Luxe Collection</option></select></div><div class="admin-field"><label>Visibility *</label><select class="field-input" id="vendor-product-status" required><option value="draft">Draft</option><option value="active">Active in Store</option></select></div></div>
          <div class="admin-field-row"><div class="admin-field"><label>Price (R) *</label><input type="number" id="vendor-product-price" min="0" step="0.01" required></div><div class="admin-field"><label>Old Price (optional)</label><input type="number" id="vendor-product-old-price" min="0" step="0.01"></div><div class="admin-field"><label>Stock *</label><input type="number" id="vendor-product-stock" min="0" step="1" value="0" required></div></div>
          <div class="admin-field"><label>Tag (optional, e.g. New / Best Seller)</label><input type="text" id="vendor-product-tag" maxlength="50"></div>
          <div class="admin-field"><label>Hair Origins (select all that apply)</label><div class="admin-quick-chips" id="vendor-hair-origin-options"><button type="button" class="admin-quick-chip" data-vendor-hair-origin="Vietnamese Virgin" onclick="toggleVendorHairOrigin('Vietnamese Virgin')">Vietnamese Virgin</button><button type="button" class="admin-quick-chip" data-vendor-hair-origin="Brazilian Virgin" onclick="toggleVendorHairOrigin('Brazilian Virgin')">Brazilian Virgin</button><button type="button" class="admin-quick-chip" data-vendor-hair-origin="Cambodian Virgin" onclick="toggleVendorHairOrigin('Cambodian Virgin')">Cambodian Virgin</button><button type="button" class="admin-quick-chip" data-vendor-hair-origin="Indian Virgin" onclick="toggleVendorHairOrigin('Indian Virgin')">Indian Virgin</button><button type="button" class="admin-quick-chip" onclick="showVendorOriginForm()">+ Add origin</button></div><div class="admin-inline-add" id="vendor-add-origin-form" hidden><input type="text" id="vendor-new-origin" maxlength="80" placeholder="Enter hair origin"><button type="button" class="admin-quick-chip" onclick="submitVendorOrigin()">Add</button><button type="button" class="admin-quick-chip" onclick="closeVendorOriginForm()">Cancel</button></div></div>
          <div class="admin-field"><label>Sizes (select all that apply)</label><div class="admin-quick-chips" id="vendor-size-options"><button type="button" class="admin-quick-chip" data-vendor-size='10"' onclick="toggleVendorSizeInches(10)">10&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='12"' onclick="toggleVendorSizeInches(12)">12&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='14"' onclick="toggleVendorSizeInches(14)">14&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='16"' onclick="toggleVendorSizeInches(16)">16&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='18"' onclick="toggleVendorSizeInches(18)">18&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='20"' onclick="toggleVendorSizeInches(20)">20&quot;</button><button type="button" class="admin-quick-chip" data-vendor-size='22"' onclick="toggleVendorSizeInches(22)">22&quot;</button><button type="button" class="admin-quick-chip" onclick="showVendorSizeForm()">+ Add size</button></div><div class="admin-inline-add" id="vendor-add-size-form" hidden><input type="text" id="vendor-new-size" maxlength="80" placeholder='e.g. 24"'><button type="button" class="admin-quick-chip" onclick="submitVendorSize()">Add</button><button type="button" class="admin-quick-chip" onclick="closeVendorSizeForm()">Cancel</button></div></div>
          <div class="admin-field"><label>Product Details (select to add or remove)</label><div class="admin-quick-chips" id="vendor-detail-options"><button type="button" class="admin-quick-chip" data-vendor-detail-key="Texture" data-vendor-detail-value="Silky Straight" onclick="toggleVendorDetail('Texture','Silky Straight')">Texture: Silky Straight</button><button type="button" class="admin-quick-chip" data-vendor-detail-key="Type" data-vendor-detail-value="100% Virgin Hair" onclick="toggleVendorDetail('Type','100% Virgin Hair')">Type: 100% Virgin Hair</button><button type="button" class="admin-quick-chip" data-vendor-detail-key="Weight" data-vendor-detail-value="130g" onclick="toggleVendorDetail('Weight','130g')">Weight: 130g</button><button type="button" class="admin-quick-chip" data-vendor-detail-key="Colour" data-vendor-detail-value="Natural Black (1B)" onclick="toggleVendorDetail('Colour','Natural Black (1B)')">Colour: Natural Black (1B)</button><button type="button" class="admin-quick-chip" data-vendor-detail-key="Cuticle" data-vendor-detail-value="Fully Aligned" onclick="toggleVendorDetail('Cuticle','Fully Aligned')">Cuticle: Fully Aligned</button><button type="button" class="admin-quick-chip" onclick="showVendorDetailForm()">+ Add detail</button></div><div class="admin-inline-add" id="vendor-add-detail-form" hidden><input type="text" id="vendor-new-detail" maxlength="251" placeholder="Name: Value"><button type="button" class="admin-quick-chip" onclick="submitVendorDetail()">Add</button><button type="button" class="admin-quick-chip" onclick="closeVendorDetailForm()">Cancel</button></div></div>
          <div class="admin-field"><label>Short Description</label><textarea id="vendor-product-short-description" maxlength="300"></textarea></div><div class="admin-field"><label>Full Description *</label><textarea id="vendor-product-description" maxlength="3000" required></textarea></div>
          <div class="admin-save-row"><button class="btn" id="vendor-product-save" type="submit">Create Product</button><button class="btn-secondary" type="button" onclick="resetVendorProductForm()">Clear</button><span class="admin-status" id="vendor-product-message" role="status"></span></div>
        </form>`;
      }

      function renderVendorImageGallery() {
        const gallery = document.getElementById("vendor-image-gallery");
        if (!gallery) return;
        const savedMarkup = vendorProductImages.map((url, index) =>
          '<div class="vendor-image-thumb"><img src="' + escapeHtml(url) + '" alt="Saved product image ' + (index + 1) + '"><button type="button" class="vendor-image-remove" onclick="removeVendorSavedImage(' + index + ')" aria-label="Remove image ' + (index + 1) + '">&times;</button>' + (index === 0 ? '<span class="vendor-image-primary">Primary</span>' : '') + '</div>'
        ).join("");
        const pendingMarkup = pendingVendorImageFiles.map((entry, index) =>
          '<div class="vendor-image-thumb"><img src="' + escapeHtml(entry.dataUrl) + '" alt="New product image ' + (index + 1) + '"><button type="button" class="vendor-image-remove" onclick="removePendingVendorImage(' + index + ')" aria-label="Remove pending image ' + (index + 1) + '">&times;</button>' + (!vendorProductImages.length && index === 0 ? '<span class="vendor-image-primary">Primary</span>' : '') + '</div>'
        ).join("");
        gallery.innerHTML = (savedMarkup + pendingMarkup) || '<p class="account-empty">No product images added yet.</p>';
      }

      async function handleVendorImagesChosen(event) {
        const files = [...event.target.files];
        event.target.value = "";
        if (!files.length) return;
        const available = 8 - vendorProductImages.length - pendingVendorImageFiles.length;
        if (files.length > available) {
          window.alert("You can add " + Math.max(available, 0) + " more image" + (available === 1 ? "." : "s."));
          return;
        }
        const allowed = ["image/jpeg", "image/png", "image/webp", "image/gif"];
        for (const file of files) {
          if (!allowed.includes(file.type) || file.size > 2 * 1024 * 1024) {
            window.alert("Each image must be a JPG, PNG, WEBP, or GIF no larger than 2 MB.");
            return;
          }
        }
        const previews = await Promise.all(files.map(async (file) => ({ file, dataUrl: await vendorFileDataUrl(file) })));
        pendingVendorImageFiles.push(...previews);
        renderVendorImageGallery();
      }

      function removePendingVendorImage(index) {
        pendingVendorImageFiles.splice(index, 1);
        renderVendorImageGallery();
      }

      async function removeVendorSavedImage(index) {
        const id = Number(document.getElementById("vendor-product-id").value);
        const imageUrl = vendorProductImages[index];
        if (!id || !imageUrl || !window.confirm("Remove this product image?")) return;
        try {
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again.");
          const response = await fetch("/api/vendor/product-image", {
            method: "DELETE",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
            body: JSON.stringify({ id, imageUrl }),
          });
          const data = await response.json().catch(() => ({}));
          if (!response.ok) throw new Error(data.error || "Unable to remove the image.");
          vendorProductImages = [...(data.image_urls || [])];
          const productIndex = vendorProductsCache.findIndex((product) => Number(product.id) === id);
          if (productIndex !== -1) vendorProductsCache[productIndex] = data;
          renderVendorImageGallery();
          await loadProducts();
          renderBestSellers();
        } catch (error) {
          window.alert(error.message || "Unable to remove the image.");
        }
      }

      function updateVendorSelectionButtons() {
        document.querySelectorAll("[data-vendor-hair-origin]").forEach((button) => {
          const selected = vendorSelectedHairOrigins.includes(button.dataset.vendorHairOrigin);
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
        document.querySelectorAll("[data-vendor-size]").forEach((button) => {
          const selected = vendorSelectedSizes.includes(button.dataset.vendorSize);
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
        document.querySelectorAll("[data-vendor-detail-key]").forEach((button) => {
          const selected = vendorSelectedDetails[button.dataset.vendorDetailKey] === button.dataset.vendorDetailValue;
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
      }

      function addVendorSelectionButton(container, text, data, handler) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "admin-quick-chip";
        button.dataset.vendorCustomSelection = "true";
        button.textContent = text;
        Object.entries(data).forEach(([key, value]) => { button.dataset[key] = value; });
        button.addEventListener("click", handler);
        container.appendChild(button);
      }

      function renderVendorCustomSelections() {
        document.querySelectorAll("[data-vendor-custom-selection]").forEach((button) => button.remove());
        const originOptions = document.getElementById("vendor-hair-origin-options");
        const sizeOptions = document.getElementById("vendor-size-options");
        const detailOptions = document.getElementById("vendor-detail-options");
        if (!originOptions || !sizeOptions || !detailOptions) return;
        vendorSelectedHairOrigins.forEach((origin) => {
          const preset = [...originOptions.querySelectorAll("[data-vendor-hair-origin]")].some((button) => button.dataset.vendorHairOrigin === origin);
          if (!preset) addVendorSelectionButton(originOptions, origin, { vendorHairOrigin: origin }, () => toggleVendorHairOrigin(origin));
        });
        vendorSelectedSizes.forEach((size) => {
          const preset = [...sizeOptions.querySelectorAll("[data-vendor-size]")].some((button) => button.dataset.vendorSize === size);
          if (!preset) addVendorSelectionButton(sizeOptions, size, { vendorSize: size }, () => toggleVendorSize(size));
        });
        Object.entries(vendorSelectedDetails).forEach(([key, value]) => {
          const preset = [...detailOptions.querySelectorAll("[data-vendor-detail-key]")].some((button) => button.dataset.vendorDetailKey === key && button.dataset.vendorDetailValue === value);
          if (!preset) addVendorSelectionButton(detailOptions, key + ": " + value, { vendorDetailKey: key, vendorDetailValue: value }, () => toggleVendorDetail(key, value));
        });
        updateVendorSelectionButtons();
      }

      function toggleVendorHairOrigin(value) {
        vendorSelectedHairOrigins = vendorSelectedHairOrigins.includes(value) ? vendorSelectedHairOrigins.filter((item) => item !== value) : [...vendorSelectedHairOrigins, value];
        renderVendorCustomSelections();
      }
      function toggleVendorSize(value) {
        vendorSelectedSizes = vendorSelectedSizes.includes(value) ? vendorSelectedSizes.filter((item) => item !== value) : [...vendorSelectedSizes, value];
        renderVendorCustomSelections();
      }
      function toggleVendorSizeInches(value) { toggleVendorSize(String(value) + '"'); }
      function toggleVendorDetail(key, value) {
        if (vendorSelectedDetails[key] === value) delete vendorSelectedDetails[key];
        else vendorSelectedDetails[key] = value;
        renderVendorCustomSelections();
      }

      function showVendorOriginForm() { document.getElementById("vendor-add-origin-form").hidden = false; document.getElementById("vendor-new-origin").focus(); }
      function closeVendorOriginForm() { document.getElementById("vendor-add-origin-form").hidden = true; document.getElementById("vendor-new-origin").value = ""; }
      function submitVendorOrigin() { const value = document.getElementById("vendor-new-origin").value.trim(); if (value && !vendorSelectedHairOrigins.includes(value)) vendorSelectedHairOrigins.push(value); renderVendorCustomSelections(); closeVendorOriginForm(); }
      function showVendorSizeForm() { document.getElementById("vendor-add-size-form").hidden = false; document.getElementById("vendor-new-size").focus(); }
      function closeVendorSizeForm() { document.getElementById("vendor-add-size-form").hidden = true; document.getElementById("vendor-new-size").value = ""; }
      function submitVendorSize() { const value = document.getElementById("vendor-new-size").value.trim(); if (value && !vendorSelectedSizes.includes(value)) vendorSelectedSizes.push(value); renderVendorCustomSelections(); closeVendorSizeForm(); }
      function showVendorDetailForm() { document.getElementById("vendor-add-detail-form").hidden = false; document.getElementById("vendor-new-detail").focus(); }
      function closeVendorDetailForm() { document.getElementById("vendor-add-detail-form").hidden = true; document.getElementById("vendor-new-detail").value = ""; }
      function submitVendorDetail() {
        const raw = document.getElementById("vendor-new-detail").value.trim();
        const [rawKey, ...rest] = raw.split(":");
        const key = String(rawKey || "").trim();
        const value = rest.join(":").trim();
        if (!key || !value) return window.alert("Please use the format Name: Value.");
        vendorSelectedDetails[key] = value;
        renderVendorCustomSelections();
        closeVendorDetailForm();
      }

      function vendorFileDataUrl(file) {
        return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result);
          reader.onerror = () => reject(new Error("Unable to read the selected image."));
          reader.readAsDataURL(file);
        });
      }

      async function loadVendorProducts(panel) {
        panel.innerHTML = '<h3>My Products</h3><p class="account-empty">Loading products…</p>';
        try {
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again.");
          const res = await fetch("/api/vendor/products", {
            headers: { Authorization: "Bearer " + token },
          });
          const data = await res.json().catch(() => []);
          if (!res.ok) throw new Error(data.error || "Unable to load products.");
          vendorProductsCache = data;
          renderVendorProducts(panel);
        } catch (error) {
          panel.innerHTML = '<p class="account-empty">' + escapeHtml(error.message) + '</p>';
        }
      }

      function renderVendorProducts(panel) {
        const rows = vendorProductsCache.length
          ? '<div style="overflow-x:auto"><table class="admin-table"><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>' +
            vendorProductsCache.map((product) => '<tr><td><strong>' + escapeHtml(product.name) + '</strong><br><small>' + escapeHtml(product.product_type) + '</small></td><td>' + formatCurrency(Number(product.price)) + '</td><td>' + Number(product.stock_quantity) + '</td><td>' + escapeHtml(product.status) + '</td><td><button class="admin-table-action" onclick="editVendorProduct(' + Number(product.id) + ')">Edit</button> <button class="admin-table-action" onclick="deleteVendorProduct(' + Number(product.id) + ')">Delete</button></td></tr>').join('') +
            '</tbody></table></div>'
          : '<p class="account-empty">You have not created any products yet.</p>';
        panel.innerHTML = '<h3>My Products</h3><p class="checkout-copy">Create and manage only the products owned by your vendor profile. Active products with stock appear in the store.</p>' + rows + '<h3 style="margin-top:32px">Product Editor</h3>' + vendorProductFormMarkup();
        resetVendorProductForm();
      }

      function resetVendorProductForm() {
        const form = document.getElementById("vendor-product-form");
        if (!form) return;
        form.reset();
        document.getElementById("vendor-product-id").value = "";
        document.getElementById("vendor-product-stock").value = "0";
        document.getElementById("vendor-product-editor-title").textContent = "Vendor · Add Product";
        document.getElementById("vendor-product-save").textContent = "Create Product";
        const message = document.getElementById("vendor-product-message");
        message.textContent = "";
        message.className = "admin-status";
        vendorSelectedHairOrigins = [];
        vendorSelectedSizes = [];
        vendorSelectedDetails = {};
        pendingVendorImageFiles = [];
        vendorProductImages = [];
        document.getElementById("vendor-img-file").value = "";
        renderVendorImageGallery();
        ["vendor-add-origin-form", "vendor-add-size-form", "vendor-add-detail-form"].forEach((id) => { document.getElementById(id).hidden = true; });
        renderVendorCustomSelections();
      }

      function editVendorProduct(id) {
        const product = vendorProductsCache.find((item) => Number(item.id) === Number(id));
        if (!product) return;
        document.getElementById("vendor-product-id").value = product.id;
        document.getElementById("vendor-product-name").value = product.name || "";
        document.getElementById("vendor-product-type").value = product.product_type || "";
        document.getElementById("vendor-product-hair-type").value = product.hair_type || "";
        document.getElementById("vendor-product-collection").value = product.collection || "everyday";
        document.getElementById("vendor-product-price").value = product.price || "";
        document.getElementById("vendor-product-old-price").value = product.old_price || "";
        document.getElementById("vendor-product-stock").value = product.stock_quantity ?? 0;
        document.getElementById("vendor-product-status").value = product.status || "draft";
        document.getElementById("vendor-product-tag").value = product.tag || "";
        document.getElementById("vendor-product-short-description").value = product.short_description || "";
        document.getElementById("vendor-product-description").value = product.description || "";
        vendorSelectedHairOrigins = [...(product.hair_origins || [])];
        vendorSelectedSizes = [...(product.sizes || [])];
        vendorSelectedDetails = { ...(product.details || {}) };
        pendingVendorImageFiles = [];
        vendorProductImages = Array.isArray(product.image_urls) && product.image_urls.length
          ? [...product.image_urls]
          : product.image_url ? [product.image_url] : [];
        document.getElementById("vendor-img-file").value = "";
        renderVendorImageGallery();
        renderVendorCustomSelections();
        document.getElementById("vendor-product-editor-title").textContent = "Vendor · Edit This Product";
        document.getElementById("vendor-product-save").textContent = "Update Product";
        document.getElementById("vendor-product-form").scrollIntoView({ behavior: "smooth", block: "start" });
      }

      async function saveVendorProduct(event) {
        event.preventDefault();
        const form = event.currentTarget;
        const message = document.getElementById("vendor-product-message");
        message.className = "admin-status";
        message.textContent = "Saving…";
        if (!form.reportValidity()) return;
        const id = document.getElementById("vendor-product-id").value;
        const payload = {
          ...(id ? { id: Number(id) } : {}),
          name: document.getElementById("vendor-product-name").value.trim(),
          productType: document.getElementById("vendor-product-type").value.trim(),
          hairType: document.getElementById("vendor-product-hair-type").value.trim(),
          collection: document.getElementById("vendor-product-collection").value,
          price: document.getElementById("vendor-product-price").value,
          oldPrice: document.getElementById("vendor-product-old-price").value,
          stockQuantity: document.getElementById("vendor-product-stock").value,
          status: document.getElementById("vendor-product-status").value,
          tag: document.getElementById("vendor-product-tag").value.trim(),
          shortDescription: document.getElementById("vendor-product-short-description").value.trim(),
          description: document.getElementById("vendor-product-description").value.trim(),
          hairOrigins: vendorSelectedHairOrigins,
          sizes: vendorSelectedSizes,
          details: vendorSelectedDetails,
        };
        try {
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again.");
          const res = await fetch("/api/vendor/products", {
            method: id ? "PATCH" : "POST",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
            body: JSON.stringify(payload),
          });
          let data = await res.json().catch(() => ({}));
          if (!res.ok) throw new Error(data.error || "Unable to save product.");
          while (pendingVendorImageFiles.length) {
            const pendingImage = pendingVendorImageFiles[0];
            const imageRes = await fetch("/api/vendor/product-image", {
              method: "POST",
              headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
              body: JSON.stringify({ id: data.id, image: pendingImage.dataUrl }),
            });
            const imageData = await imageRes.json().catch(() => ({}));
            if (!imageRes.ok) throw new Error(imageData.error || "Unable to upload the product image.");
            data = imageData;
            vendorProductImages = [...(data.image_urls || [])];
            pendingVendorImageFiles.shift();
          }
          await loadProducts();
          renderBestSellers();
          const index = vendorProductsCache.findIndex((product) => Number(product.id) === Number(data.id));
          if (index === -1) vendorProductsCache.unshift(data);
          else vendorProductsCache[index] = data;
          renderVendorProducts(document.getElementById("account-panel"));
          const savedMessage = document.getElementById("vendor-product-message");
          savedMessage.textContent = "Saved.";
          savedMessage.className = "admin-status ok";
        } catch (error) {
          message.textContent = error.message;
          message.className = "admin-status err";
          renderVendorImageGallery();
        }
      }

      async function deleteVendorProduct(id) {
        if (!window.confirm("Delete this product? This cannot be undone.")) return;
        try {
          const token = await getSupabaseAccessToken();
          const res = await fetch("/api/vendor/products?id=" + encodeURIComponent(id), {
            method: "DELETE",
            headers: { Authorization: "Bearer " + token },
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) throw new Error(data.error || "Unable to delete product.");
          openAccount(null, "vendor-products");
        } catch (error) {
          window.alert(error.message);
        }
      }

      async function loadVendorOrders(panel) {
        panel.innerHTML = '<h3>My Orders</h3><p class="account-empty">Loading vendor orders…</p>';
        try {
          const token = await getSupabaseAccessToken();
          if (!token) throw new Error("Please sign in again.");
          const res = await fetch("/api/vendor/orders", {
            headers: { Authorization: "Bearer " + token },
          });
          const orders = await res.json().catch(() => []);
          if (!res.ok) throw new Error(orders.error || "Unable to load vendor orders.");
          const statusOptions = ["Order received", "Processing", "Ready for dispatch", "Dispatched", "Completed", "Cancelled"];
          panel.innerHTML = '<h3>My Orders</h3><p class="checkout-copy">Only orders containing products owned by your vendor profile appear here.</p>' + (orders.length ? '<div style="overflow-x:auto"><table class="admin-table"><thead><tr><th>Order</th><th>Customer & Delivery</th><th>Your Items</th><th>Subtotal</th><th>Status</th></tr></thead><tbody>' + orders.map((order) => '<tr><td><strong>' + escapeHtml(order.order_number) + '</strong><br><small>' + new Date(order.created_at).toLocaleDateString() + '</small></td><td>' + escapeHtml(order.customer_email) + '<br>' + escapeHtml(order.customer_phone) + '<br><small>' + escapeHtml(order.delivery_address) + '</small></td><td>' + (order.items || []).map((item) => escapeHtml(item.quantity + ' × ' + item.name)).join('<br>') + '</td><td>' + formatCurrency(Number(order.subtotal)) + '</td><td><select onchange="updateVendorOrderStatus(' + Number(order.id) + ', this.value)">' + statusOptions.map((status) => '<option' + (order.status === status ? ' selected' : '') + '>' + status + '</option>').join('') + '</select></td></tr>').join('') + '</tbody></table></div>' : '<p class="account-empty">No orders for your products yet.</p>');
        } catch (error) {
          panel.innerHTML = '<p class="account-empty">' + escapeHtml(error.message) + '</p>';
        }
      }

      async function updateVendorOrderStatus(id, status) {
        try {
          const token = await getSupabaseAccessToken();
          const res = await fetch("/api/vendor/orders", {
            method: "PATCH",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
            body: JSON.stringify({ id, status }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) throw new Error(data.error || "Unable to update order.");
        } catch (error) {
          window.alert(error.message);
          openAccount(null, "vendor-orders");
        }
      }

      async function openAccount(e, tab, skipRouteUpdate) {
        if (e) e.preventDefault();
        if (!["customer", "vendor"].includes(currentUserRole)) return;
        const routePath = accountTabRoutes[tab];
        if (!skipRouteUpdate && routePath) {
          const route = accountPageRoutes[routePath];
          if (route.portal === "vendor" && currentUser?.isVendor) {
            currentPortal = "vendor";
            safeLocalStorageSet("NAKA_portal_mode", "vendor");
          } else {
            currentPortal = "customer";
            safeLocalStorageSet("NAKA_portal_mode", "customer");
          }
          history.pushState(null, "", routePath);
          updateUserUI();
        }
        const view = document.getElementById("account-view");
        view.style.display = "block";
        view.scrollIntoView({ behavior: "smooth", block: "start" });
        const isVendorPortal = currentPortal === "vendor" && currentUser?.isVendor;
        const tabs = isVendorPortal
          ? ["vendor-products", "vendor-orders", "vendor", "profile"]
          : ["profile", "orders", "wishlist", "addresses", "vendor"];
        view.innerHTML =
          '<h1>' +
          (isVendorPortal ? "Vendor Dashboard" : "My Account") +
          '</h1><p>' +
          (isVendorPortal
            ? "Manage your NAKA Hair vendor profile."
            : "Manage your NAKA Hair account.") +
          '</p><div class="account-tabs">' +
          tabs
            .map(
              (name) =>
                '<a href="' +
                accountTabRoutes[name] +
                '" class="' +
                (tab === name ? "active" : "") +
                '" onclick="openAccount(event, \'' +
                name +
                "')\">" +
                {
                  profile: "My Profile",
                  orders: "My Orders",
                  wishlist: "Wishlist",
                  addresses: "Saved Addresses",
                  vendor: "Become a Vendor",
                  "vendor-products": "My Products",
                  "vendor-orders": "My Orders",
                }[name] +
                "</a>",
            )
            .join("") +
          '</div><div class="account-panel" id="account-panel"></div>';
        const panel = document.getElementById("account-panel");
        if (tab === "vendor-products" && isVendorPortal) {
          await loadVendorProducts(panel);
        } else if (tab === "vendor-orders" && isVendorPortal) {
          await loadVendorOrders(panel);
        } else if (tab === "profile") {
          panel.innerHTML =
            '<h3>My Profile</h3><div class="form-grid"><div class="form-field"><label class="field-label">First Name</label><input class="field-input" id="account-first" value="' +
            escapeHtml(currentUser.firstName) +
            '"></div><div class="form-field"><label class="field-label">Last Name</label><input class="field-input" id="account-last" value="' +
            escapeHtml(currentUser.lastName) +
            '"></div><div class="form-field full"><label class="field-label">Phone Number</label><input class="field-input" id="account-phone" value="' +
            escapeHtml(currentUser.phone) +
            '"></div><div class="form-field full"><label class="field-label">New Password (optional)</label><input type="password" class="field-input" id="account-password"></div></div><div class="modal-actions"><button class="btn" onclick="saveAccount()">Save Changes</button></div><p id="account-message"></p>';
        } else if (tab === "orders") {
          panel.innerHTML =
            '<h3>My Orders</h3><p class="account-empty">Loading orders…</p>';
          try {
            const token = await getSupabaseAccessToken();
            const res = await fetch("/api/orders", {
              headers: { Authorization: "Bearer " + token },
            });
            const orders = await res.json();
            panel.innerHTML =
              "<h3>My Orders</h3>" +
              (orders.length
                ? orders
                    .map(
                      (o) =>
                        '<div class="summary-row"><span><strong>' +
                        escapeHtml(o.order_number) +
                        "</strong><br>" +
                        new Date(o.created_at).toLocaleDateString() +
                        "</span><strong>" +
                        formatCurrency(o.total) +
                        "</strong></div>",
                    )
                    .join("")
                : '<p class="account-empty">You have not placed any orders yet.</p>');
          } catch (_) {
            panel.innerHTML =
              '<p class="account-empty">Unable to load orders.</p>';
          }
        } else if (tab === "wishlist")
          panel.innerHTML =
            '<h3>Wishlist</h3><p class="account-empty">Your saved favourites will appear here.</p>';
        else if (tab === "vendor") {
          if (currentUser?.isVendor) {
            panel.innerHTML =
              '<h3>Vendor Profile</h3><p class="checkout-copy"><strong>' +
              escapeHtml(currentUser.vendorBusinessName || "Your business") +
              '</strong> is approved and active.</p><p id="vendor-message" class="modal-success"></p>';
          } else {
            panel.innerHTML =
              '<h3>Vendor Application</h3><p class="checkout-copy">Request a secure vendor application link. Once you receive it by email, return here to complete your business details and activate your vendor profile.</p><button class="btn" onclick="requestVendorApplication()">Email Me the Application Link</button><div id="vendor-application-form" style="display:none; margin-top:24px"><div class="form-grid"><div class="form-field"><label class="field-label">Business Name *</label><input class="field-input" id="vendor-business-name" maxlength="160" required></div><div class="form-field"><label class="field-label">Contact Person *</label><input class="field-input" id="vendor-contact-name" maxlength="120" required></div><div class="form-field"><label class="field-label">Business Phone *</label><input class="field-input" id="vendor-phone" type="tel" maxlength="50" required></div><div class="form-field"><label class="field-label">Business Type *</label><select class="field-input" id="vendor-business-type" required><option value="">Select a type</option><option value="salon">Salon</option><option value="stylist">Hair Stylist</option><option value="retailer">Retailer</option><option value="wholesaler">Wholesaler</option><option value="online-store">Online Store</option><option value="other">Other</option></select></div><div class="form-field"><label class="field-label">Registration Number</label><input class="field-input" id="vendor-registration-number" maxlength="100"></div><div class="form-field"><label class="field-label">Tax / VAT Number</label><input class="field-input" id="vendor-tax-number" maxlength="100"></div><div class="form-field"><label class="field-label">Website</label><input class="field-input" id="vendor-website-url" type="url" maxlength="500" placeholder="https://"></div><div class="form-field"><label class="field-label">Social Profile</label><input class="field-input" id="vendor-social-media-url" type="url" maxlength="500" placeholder="https://"></div><div class="form-field full"><label class="field-label">Street Address *</label><input class="field-input" id="vendor-street-address" maxlength="200" required></div><div class="form-field"><label class="field-label">City *</label><input class="field-input" id="vendor-city" maxlength="100" required></div><div class="form-field"><label class="field-label">Province *</label><select class="field-input" id="vendor-province" required><option value="">Select a province</option><option>Eastern Cape</option><option>Free State</option><option>Gauteng</option><option>KwaZulu-Natal</option><option>Limpopo</option><option>Mpumalanga</option><option>North West</option><option>Northern Cape</option><option>Western Cape</option></select></div><div class="form-field"><label class="field-label">Postal Code *</label><input class="field-input" id="vendor-postal-code" maxlength="20" inputmode="numeric" required></div><div class="form-field full"><label class="field-label">Tell Us About Your Business *</label><textarea class="field-input" id="vendor-business-description" rows="5" maxlength="2000" placeholder="Describe your services, customers, and the hair products you are interested in." required></textarea></div></div><div class="modal-actions"><button class="btn" onclick="completeVendorApplication()">Create Vendor Profile</button></div></div><p id="vendor-message" class="modal-error"></p>';
          }
          if (!currentUser?.isVendor && window.location.hash === "#vendor-application") {
            document.getElementById("vendor-application-form").style.display = "block";
            history.replaceState(null, "", window.location.pathname);
          }
        }
        else {
          panel.innerHTML =
            '<h3>Saved Addresses</h3><div id="saved-addresses" class="account-empty">Loading addresses…</div><h3 style="margin-top:28px">Add Address</h3><div class="form-grid"><div class="form-field"><label class="field-label">Label</label><input class="field-input" id="address-label" value="Home"></div><div class="form-field"><label class="field-label">Address</label><input class="field-input" id="address-address"></div><div class="form-field"><label class="field-label">Province</label><input class="field-input" id="address-province"></div><div class="form-field"><label class="field-label">City</label><input class="field-input" id="address-city"></div><div class="form-field"><label class="field-label">Street</label><input class="field-input" id="address-street"></div><div class="form-field"><label class="field-label">Postal Code</label><input class="field-input" id="address-postal"></div></div><div class="modal-actions"><button class="btn" onclick="saveAddress()">Save Address</button></div>';
          try {
            const res = await fetch("/api/addresses", {
              headers: { Authorization: "Bearer " + authToken },
            });
            const rows = await res.json();
            document.getElementById("saved-addresses").innerHTML = rows.length
              ? rows
                  .map(
                    (a) =>
                      '<div class="summary-row"><span><strong>' +
                      escapeHtml(a.label) +
                      "</strong><br>" +
                      escapeHtml(
                        [
                          a.address,
                          a.street,
                          a.city,
                          a.province,
                          a.postal_code,
                        ].join(", "),
                      ) +
                      "</span></div>",
                  )
                  .join("")
              : "No saved addresses yet.";
          } catch (_) {
            document.getElementById("saved-addresses").textContent =
              "Unable to load addresses.";
          }
        }
      }
      function escapeHtml(value) {
        const d = document.createElement("div");
        d.textContent = value || "";
        return d.innerHTML;
      }
      async function saveAccount() {
        const msg = document.getElementById("account-message");
        try {
          const res = await fetch("/api/account", {
            method: "PUT",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Bearer " + authToken,
            },
            body: JSON.stringify({
              firstName: document.getElementById("account-first").value,
              lastName: document.getElementById("account-last").value,
              phone: document.getElementById("account-phone").value,
              password: document.getElementById("account-password").value,
            }),
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error);
          currentUser = data.user;
          currentUserName = data.user.firstName;
          updateUserUI();
          msg.textContent = "Profile updated.";
        } catch (e) {
          msg.textContent = e.message || "Unable to update profile.";
        }
      }
      async function saveAddress() {
        try {
          const res = await fetch("/api/addresses", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Bearer " + authToken,
            },
            body: JSON.stringify({
              label: document.getElementById("address-label").value,
              address: document.getElementById("address-address").value,
              province: document.getElementById("address-province").value,
              city: document.getElementById("address-city").value,
              street: document.getElementById("address-street").value,
              postalCode: document.getElementById("address-postal").value,
            }),
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error);
          openAccount(null, "addresses");
        } catch (e) {
          alert(e.message || "Unable to save address.");
        }
      }

      function escapeAdminText(value) {
        return String(value ?? "").replace(
          /[&<>\"]/g,
          (char) =>
            ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[char],
        );
      }

      function openAdminDashboard() {
        if (!isAdmin()) return;
        document.getElementById("admin-dashboard").classList.add("open");
        loadAdminDashboard("products");
      }

      function closeAdminDashboard() {
        document.getElementById("admin-dashboard").classList.remove("open");
      }

      async function loadAdminDashboard(tab) {
        if (!isAdmin()) return;
        document
          .querySelectorAll("[data-admin-tab]")
          .forEach((button) =>
            button.classList.toggle("active", button.dataset.adminTab === tab),
          );
        const content = document.getElementById("admin-dashboard-content");
        if (tab === "products") {
          content.innerHTML =
            '<h2>Products</h2><p class="admin-dashboard-copy">Edit product information, prices, images, sizes and hair origins.</p><table class="admin-table"><thead><tr><th>Product</th><th>Collection</th><th>Base price</th><th></th></tr></thead><tbody>' +
            products
              .map(
                (product) =>
                  "<tr><td>" +
                  escapeAdminText(product.name) +
                  "</td><td>" +
                  escapeAdminText(product.collection) +
                  "</td><td>" +
                  escapeAdminText(product.price) +
                  '</td><td><button class="admin-table-action" onclick="editProductFromDashboard(' +
                  product.id +
                  ')">Edit</button></td></tr>',
              )
              .join("") +
            "</tbody></table>";
          return;
        }
        content.innerHTML = '<p class="admin-dashboard-copy">Loading…</p>';
        try {
          const res = await fetch("/api/admin/" + tab, {
            headers: { Authorization: "Bearer " + authToken },
          });
          const data = await res.json();
          if (!res.ok)
            throw new Error(data.error || "Unable to load this section.");
          if (tab === "orders") {
            content.innerHTML =
              '<h2>Orders</h2><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody>' +
              data
                .map(
                  (order) =>
                    "<tr><td>" +
                    escapeAdminText(order.order_number) +
                    "</td><td>" +
                    escapeAdminText(order.email) +
                    "</td><td>" +
                    formatCurrency(order.total) +
                    '</td><td><select onchange="updateAdminOrderStatus(' +
                    order.id +
                    ',this.value)">' +
                    [
                      "Order received",
                      "Processing",
                      "Dispatched",
                      "Delivered",
                      "Cancelled",
                    ]
                      .map(
                        (status) =>
                          "<option" +
                          (order.status === status ? " selected" : "") +
                          ">" +
                          status +
                          "</option>",
                      )
                      .join("") +
                    "</select></td></tr>",
                )
                .join("") +
              "</tbody></table>";
          } else if (tab === "customers") {
            content.innerHTML =
              '<h2>Customers</h2><table class="admin-table"><thead><tr><th>Customer</th><th>Email</th><th>Phone</th><th>Orders</th><th>Spend</th></tr></thead><tbody>' +
              data
                .map(
                  (customer) =>
                    "<tr><td>" +
                    escapeAdminText(
                      customer.first_name + " " + customer.last_name,
                    ) +
                    "</td><td>" +
                    escapeAdminText(customer.email) +
                    "</td><td>" +
                    escapeAdminText(customer.phone) +
                    "</td><td>" +
                    customer.order_count +
                    "</td><td>" +
                    formatCurrency(customer.total_spend) +
                    "</td></tr>",
                )
                .join("") +
              "</tbody></table>";
          } else if (tab === "vendor-requests") {
            content.innerHTML = '<h2>Vendor Requests</h2><table class="admin-table"><thead><tr><th>Applicant</th><th>Business</th><th>Phone</th><th>Status</th><th></th></tr></thead><tbody>' + data.map((request) => '<tr><td>' + escapeAdminText(request.email) + '</td><td>' + escapeAdminText(request.business_name || "—") + '</td><td>' + escapeAdminText(request.phone || "—") + '</td><td>' + escapeAdminText(request.status) + '</td><td>' + (request.status === "pending" ? '<button class="admin-table-action" onclick="approveVendorRequest(' + request.id + ')">Approve</button>' : "") + '</td></tr>').join("") + "</tbody></table>";
          } else if (tab === "staff") {
            content.innerHTML =
              '<h2>Staff Accounts</h2><p class="admin-dashboard-copy">Create admin users who can manage products, orders, customers and reports.</p><form class="form-grid" onsubmit="createAdminUser(event)"><div class="form-field"><label class="field-label">Username</label><input class="field-input" id="new-admin-username" autocomplete="username" required></div><div class="form-field"><label class="field-label">Temporary Password</label><input class="field-input" id="new-admin-password" type="password" autocomplete="new-password" minlength="8" required></div><div class="form-field full"><button class="btn" type="submit">Create Admin User</button><p class="modal-error" id="new-admin-message"></p></div></form><h3 style="margin-top:32px">Current Staff</h3><table class="admin-table"><thead><tr><th>Username</th></tr></thead><tbody>' +
              (data.length
                ? data
                    .map(
                      (staff) =>
                        "<tr><td>" +
                        escapeAdminText(staff.username) +
                        "</td></tr>",
                    )
                    .join("")
                : '<tr><td class="admin-dashboard-empty">No staff accounts yet.</td></tr>') +
              "</tbody></table>";
          } else {
            content.innerHTML =
              '<h2>Reports</h2><p class="admin-dashboard-copy">Live store performance overview.</p><div class="admin-report-grid"><div class="admin-report-card"><span>Revenue</span><strong>' +
              formatCurrency(data.revenue) +
              '</strong></div><div class="admin-report-card"><span>Orders</span><strong>' +
              data.order_count +
              '</strong></div><div class="admin-report-card"><span>30-day orders</span><strong>' +
              data.recentOrders +
              '</strong></div><div class="admin-report-card"><span>Customers</span><strong>' +
              data.customerCount +
              "</strong></div></div>";
          }
        } catch (error) {
          content.innerHTML =
            '<p class="admin-dashboard-empty">' +
            escapeAdminText(error.message) +
            "</p>";
        }
      }

      function editProductFromDashboard(id) {
        const product = products.find((item) => item.id === id);
        if (!product) return;
        closeAdminDashboard();
        adminEditorOpen = true;
        openPDP(product, true);
      }

      async function updateAdminOrderStatus(id, status) {
        const res = await fetch("/api/admin/orders/" + id, {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + authToken,
          },
          body: JSON.stringify({ status }),
        });
        if (!res.ok) {
          loadAdminDashboard("orders");
        }
      }

      async function createAdminUser(event) {
        event.preventDefault();
        const message = document.getElementById("new-admin-message");
        const username = document.getElementById("new-admin-username").value.trim();
        const password = document.getElementById("new-admin-password").value;
        message.style.display = "none";
        try {
          const res = await fetch("/api/admin/staff", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: "Bearer " + authToken,
            },
            body: JSON.stringify({ username, password }),
          });
          const data = await res.json();
          if (!res.ok) throw new Error(data.error || "Unable to create admin user.");
          loadAdminDashboard("staff");
        } catch (error) {
          message.textContent = error.message;
          message.style.display = "block";
        }
      }

      async function approveVendorRequest(id) {
        const res = await fetch("/api/admin/vendor-requests/" + id + "/approve", { method: "POST", headers: { Authorization: "Bearer " + authToken } });
        if (res.ok) loadAdminDashboard("vendor-requests");
      }

      function updateUserUI() {
        const badgeWrap = document.getElementById("user-badge-wrap");
        const roleBadge = document.getElementById("user-role-badge");
        const loginLink = document.getElementById("login-nav-link");
        const vendorLoginLink = document.getElementById("vendor-login-nav-link");
        const customerMenu = document.getElementById("customer-menu");
        const vendorAccountLink = document.getElementById("vendor-account-link");
        const vendorProductsLink = document.getElementById("vendor-products-link");
        const vendorOrdersLink = document.getElementById("vendor-orders-link");
        const adminLogout = document.getElementById("admin-logout");
        const dashboardButton = document.getElementById("admin-dashboard-btn");
        const hasSession = !!currentUserRole;
        badgeWrap.style.display = hasSession ? "inline-flex" : "none";
        loginLink.style.display = hasSession ? "none" : "inline";
        vendorLoginLink.style.display = hasSession ? "none" : "inline";
        customerMenu.style.display =
          ["customer", "vendor"].includes(currentUserRole) ? "inline-flex" : "none";
        adminLogout.style.display = isAdmin() ? "inline-block" : "none";
        dashboardButton.style.display = isAdmin() ? "inline-block" : "none";
        const isVendorPortal = currentPortal === "vendor" && currentUser?.isVendor;
        document.querySelectorAll(".nav-cart, .col-cart-top, .pdp-cart-top").forEach((element) => {
          element.style.display = isVendorPortal ? "none" : "";
        });
        const productCartButton = document.getElementById("pdp-cart-btn");
        productCartButton.style.display = isVendorPortal ? "none" : "";
        if (isVendorPortal) {
          document.getElementById("cart-overlay").classList.remove("open");
          checkoutStep = "cart";
          updateBodyScrollLock();
        }
        roleBadge.style.display = isAdmin() || isVendorPortal ? "inline-block" : "none";
        vendorAccountLink.style.display = currentUser?.isVendor ? "block" : "none";
        vendorProductsLink.style.display = isVendorPortal ? "block" : "none";
        vendorOrdersLink.style.display = isVendorPortal ? "block" : "none";
        document.getElementById("customer-greeting").textContent =
          ["customer", "vendor"].includes(currentUserRole)
            ? isVendorPortal
              ? "Vendor, " + (currentUser?.vendorBusinessName || currentUserName || "there")
              : "Hi, " + (currentUserName || "there")
            : "";
        roleBadge.textContent = isAdmin() ? "Admin" : isVendorPortal ? "Vendor" : "";

        const editTrigger = document.getElementById("admin-edit-trigger");
        const ownedVendorProduct = currentUser?.isVendor && currentPdpProduct?.source === "vendor" && vendorProductsCache.some((product) => Number(product.id) === Number(currentPdpProduct.vendorProductId));
        editTrigger.style.display =
          currentPdpProduct && (isAdmin() || ownedVendorProduct) ? "inline-block" : "none";
        editTrigger.textContent = isAdmin() ? "Edit product" : "Edit my product";
        const panel = document.getElementById("admin-edit-panel");
        const showPanel = isAdmin() && currentPdpProduct && adminEditorOpen;
        panel.style.display = showPanel ? "block" : "none";
        if (showPanel) fillAdminPanel(currentPdpProduct);
      }

      function openAdminEditor() {
        if (!isAdmin() || !currentPdpProduct) return;
        adminEditorOpen = true;
        updateUserUI();
        document.getElementById("admin-edit-panel").scrollIntoView({
          behavior: "smooth",
          block: "start",
        });
      }

      async function openProductEditor() {
        if (isAdmin()) return openAdminEditor();
        const id = currentPdpProduct?.vendorProductId;
        const owned = currentUser?.isVendor && vendorProductsCache.some((product) => Number(product.id) === Number(id));
        if (!owned) return;
        await openAccount(null, "vendor-products");
        editVendorProduct(id);
      }

      function closeAdminEditor() {
        adminEditorOpen = false;
        pendingAdminImageFile = null;
        document.getElementById("admin-img-file").value = "";
        updateUserUI();
      }

      function fillAdminPanel(p) {
        document.getElementById("admin-add-origin-form").hidden = true;
        document.getElementById("admin-add-detail-form").hidden = true;
        document.getElementById("admin-new-origin").value = "";
        document.getElementById("admin-new-detail").value = "";
        document.getElementById("admin-f-name").value = p.name || "";
        document.getElementById("admin-f-price").value = p.price || "";
        document.getElementById("admin-f-oldprice").value = p.oldPrice || "";
        document.getElementById("admin-f-tag").value = p.tag || "";
        selectedHairOrigins = [...(p.hairOrigins || [])];
        selectedSizes = [...(p.sizes || [])];
        selectedDetails = { ...(p.details || {}) };
        renderCustomSelectionButtons();
        updateSelectionButtons();
        document.getElementById("admin-f-shortdesc").value = p.shortDesc || "";
        document.getElementById("admin-f-desc").value = p.desc || "";

        const preview = document.getElementById("admin-img-preview");
        preview.innerHTML = p.image
          ? '<img src="' + p.image + '" alt="">'
          : "<span>IMG</span>";

        pendingAdminImageFile = null;
        const statusEl = document.getElementById("admin-status");
        statusEl.textContent = "";
        statusEl.className = "admin-status";
      }

      function handleAdminImageChosen(e) {
        const file = e.target.files[0];
        if (!file) return;
        pendingAdminImageFile = file;
        const preview = document.getElementById("admin-img-preview");
        const reader = new FileReader();
        reader.onload = () =>
          (preview.innerHTML = '<img src="' + reader.result + '" alt="">');
        reader.readAsDataURL(file);
      }

      function updateSelectionButtons() {
        document.querySelectorAll("[data-hair-origin]").forEach((button) => {
          const selected = selectedHairOrigins.includes(
            button.dataset.hairOrigin,
          );
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
        document.querySelectorAll("[data-size]").forEach((button) => {
          const selected = selectedSizes.includes(button.dataset.size);
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
        document.querySelectorAll("[data-detail-key]").forEach((button) => {
          const selected =
            selectedDetails[button.dataset.detailKey] ===
            button.dataset.detailValue;
          button.classList.toggle("is-selected", selected);
          button.setAttribute("aria-pressed", String(selected));
        });
      }

      function addCustomSelectionButton(container, text, attributes, onClick) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "admin-quick-chip";
        button.textContent = text;
        button.dataset.customSelection = "true";
        Object.entries(attributes).forEach(([key, value]) => {
          button.dataset[key] = value;
        });
        button.addEventListener("click", onClick);
        container.appendChild(button);
      }

      function renderCustomSelectionButtons() {
        document
          .querySelectorAll("[data-custom-selection]")
          .forEach((button) => button.remove());

        const originOptions = document.getElementById(
          "admin-hair-origin-options",
        );
        selectedHairOrigins.forEach((origin) => {
          const isPreset = [
            ...document.querySelectorAll("[data-hair-origin]"),
          ].some((button) => button.dataset.hairOrigin === origin);
          if (!isPreset) {
            addCustomSelectionButton(
              originOptions,
              origin,
              { hairOrigin: origin },
              () => toggleHairOrigin(origin),
            );
          }
        });

        const detailOptions = document.getElementById("admin-detail-options");
        Object.entries(selectedDetails).forEach(([key, value]) => {
          const isPreset = [
            ...document.querySelectorAll("[data-detail-key]"),
          ].some(
            (button) =>
              button.dataset.detailKey === key &&
              button.dataset.detailValue === value,
          );
          if (!isPreset) {
            addCustomSelectionButton(
              detailOptions,
              `${key}: ${value}`,
              { detailKey: key, detailValue: value },
              () => toggleDetail(key, value),
            );
          }
        });
      }

      function toggleHairOrigin(value) {
        selectedHairOrigins = selectedHairOrigins.includes(value)
          ? selectedHairOrigins.filter((item) => item !== value)
          : [...selectedHairOrigins, value];
        renderCustomSelectionButtons();
        updateSelectionButtons();
      }

      function addCustomHairOrigin() {
        const form = document.getElementById("admin-add-origin-form");
        form.hidden = false;
        document.getElementById("admin-new-origin").focus();
      }

      function closeCustomHairOrigin() {
        const form = document.getElementById("admin-add-origin-form");
        form.hidden = true;
        document.getElementById("admin-new-origin").value = "";
      }

      function submitCustomHairOrigin(event) {
        event.preventDefault();
        const input = document.getElementById("admin-new-origin");
        const origin = input.value.trim();
        if (!origin) return;
        if (!selectedHairOrigins.includes(origin)) {
          selectedHairOrigins = [...selectedHairOrigins, origin];
        }
        renderCustomSelectionButtons();
        updateSelectionButtons();
        closeCustomHairOrigin();
      }

      function toggleSize(value) {
        selectedSizes = selectedSizes.includes(value)
          ? selectedSizes.filter((item) => item !== value)
          : [...selectedSizes, value];
        updateSelectionButtons();
      }

      function toggleDetail(key, value) {
        if (selectedDetails[key] === value) {
          delete selectedDetails[key];
        } else {
          selectedDetails[key] = value;
        }
        renderCustomSelectionButtons();
        updateSelectionButtons();
      }

      function addCustomDetail() {
        const form = document.getElementById("admin-add-detail-form");
        form.hidden = false;
        document.getElementById("admin-new-detail").focus();
      }

      function closeCustomDetail() {
        const form = document.getElementById("admin-add-detail-form");
        form.hidden = true;
        document.getElementById("admin-new-detail").value = "";
      }

      function submitCustomDetail(event) {
        event.preventDefault();
        const input = document.getElementById("admin-new-detail");
        const detail = input.value.trim();
        if (!detail) return;
        const [key, ...rest] = detail.split(":");
        const detailKey = key && key.trim();
        const detailValue = rest.join(":").trim();
        if (!detailKey || !detailValue) {
          window.alert("Please use the format Name: Value.");
          return;
        }
        selectedDetails[detailKey] = detailValue;
        renderCustomSelectionButtons();
        updateSelectionButtons();
        closeCustomDetail();
      }

      async function saveAdminEdits() {
        if (!currentPdpProduct || !isAdmin()) return;
        const statusEl = document.getElementById("admin-status");
        statusEl.className = "admin-status";
        statusEl.textContent = "Saving…";

        const patch = {
          name: document.getElementById("admin-f-name").value.trim(),
          price: document.getElementById("admin-f-price").value.trim(),
          oldPrice:
            document.getElementById("admin-f-oldprice").value.trim() || null,
          tag: document.getElementById("admin-f-tag").value.trim(),
          hairOrigins: selectedHairOrigins,
          sizes: selectedSizes,
          details: selectedDetails,
          shortDesc: document.getElementById("admin-f-shortdesc").value.trim(),
          desc: document.getElementById("admin-f-desc").value.trim(),
        };

        try {
          const res = await fetch(
            "/api/admin/products/" + currentPdpProduct.id,
            {
              method: "PUT",
              headers: {
                "Content-Type": "application/json",
                Authorization: "Bearer " + authToken,
              },
              body: JSON.stringify(patch),
            },
          );
          if (res.status === 401) {
            logout();
            statusEl.textContent = "Session expired — please log in again.";
            statusEl.className = "admin-status err";
            return;
          }
          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            throw new Error(body.error || "Save failed");
          }
          let updated = await res.json();

          if (pendingAdminImageFile) {
            const fd = new FormData();
            fd.append("image", pendingAdminImageFile);
            const imgRes = await fetch(
              "/api/admin/products/" + currentPdpProduct.id + "/image",
              {
                method: "POST",
                headers: { Authorization: "Bearer " + authToken },
                body: fd,
              },
            );
            if (!imgRes.ok) {
              const body = await imgRes.json().catch(() => ({}));
              throw new Error(body.error || "Image upload failed");
            }
            updated = await imgRes.json();
          }

          applyProductUpdate(currentPdpProduct.id, updated);
          currentPdpProduct = updated;
          openPDP(updated, true); // refresh the PDP and keep the editor open
          statusEl.textContent = "Saved.";
          statusEl.className = "admin-status ok";
        } catch (e) {
          statusEl.textContent =
            e.message || "Could not save changes. Try again.";
          statusEl.className = "admin-status err";
        }
      }

      // Updates the in-memory catalogue and re-renders any views currently
      // showing this product, so an edit appears everywhere immediately.
      function applyProductUpdate(id, patch) {
        const idx = products.findIndex((pr) => pr.id === id);
        if (idx > -1) Object.assign(products[idx], patch);

        renderBestSellers();

        const colPage = document.getElementById("col-page");
        if (colPage.classList.contains("open")) {
          const openKey = colPage.dataset.currentCollection;
          if (openKey) openCollection(openKey);
        }
      }

      // ─────────────────────────────────────────────────────────
      // INIT
      // ─────────────────────────────────────────────────────────
      (async function init() {
        await loadProducts();
        renderBestSellers();
        await restoreCustomerOrAdminSession();
        if (window.location.hash === "#vendor-application" && currentUser) {
          openAccount(null, "vendor");
        }
        showAccountRoute();
        if (window.location.search.includes("admin=1")) {
          showAdminLogin();
        }
      })();
